// Picks a food icon for a meal name. Data is generated by scripts/food-icons.mjs (Fluent Emoji Flat SVGs, emojilib words).
import type { MealSlot } from './db'
import data from './food-icons.json'

export const FOOD_ICONS = data as { slots: Record<MealSlot, number>; icons: string[]; words: Record<string, number> }

function lookup(word: string): number | undefined {
  const w = FOOD_ICONS.words
  return w[word] ?? (word.endsWith('es') ? w[word.slice(0, -2)] : undefined) ?? (word.endsWith('s') ? w[word.slice(0, -1)] : undefined)
}

/** Icon index: the first word (or two-word phrase, e.g. "peanut butter") in the name that names a food; else the slot's default. */
export function foodIconIndex(name: string, slot: MealSlot): number {
  const words = name.toLowerCase().match(/[\p{L}]+/gu) ?? []
  for (let i = 0; i < words.length; i++) {
    const hit = (i + 1 < words.length ? lookup(`${words[i]} ${words[i + 1]}`) : undefined) ?? lookup(words[i])
    if (hit !== undefined) return hit
  }
  return FOOD_ICONS.slots[slot]
}

/** URL of the bundled SVG for a meal name (public/food/<slug>.svg). */
export function foodIconUrl(name: string, slot: MealSlot): string {
  return `/food/${FOOD_ICONS.icons[foodIconIndex(name, slot)]}.svg`
}
